-- Append inside rollback-only migration transaction; uses exclusively synthetic queue rows.
DO $fixture$ DECLARE p jsonb;r jsonb; aid uuid:='00000000-0000-4000-8000-00000000a121'; jid uuid:='00000000-0000-4000-8000-00000000a122'; BEGIN
