p:=jsonb_build_object('promptVersion','marketing-performance-v1','analysisType','weekly_performance','snapshotHash',repeat('a',64),'sourceManifestHash',repeat('b',64),'period',jsonb_build_object('key','this_week','currentStart','2026-09-21','currentEnd','2026-09-24'),'evidence',jsonb_build_array(jsonb_build_object('id','e1')),'coverage',jsonb_build_object('prepared',1,'sent',1,'dropped',0));
r:=ccpun_admin.admin_prepare_marketing_analysis(aid,p,repeat('c',64),'[]');IF r->>'status'<>'prepared' OR (r->>'reused')::boolean THEN RAISE EXCEPTION 'PREPARE_FAIL';END IF;
r:=ccpun_admin.admin_prepare_marketing_analysis(gen_random_uuid(),p,repeat('c',64),'[]');IF NOT(r->>'reused')::boolean OR r->>'analysisId'<>aid::text THEN RAISE EXCEPTION 'IDEMPOTENCY_FAIL';END IF;
r:=ccpun_admin.admin_marketing_analysis_status(aid);IF r->>'status'<>'prepared' OR (r->>'workerSucceeded')::boolean THEN RAISE EXCEPTION 'PREPARED_NOT_READY_FAIL';END IF;
