UPDATE ccpun_admin.marketing_analysis SET job_id=jid WHERE analysis_id=aid;
r:=ccpun_admin.admin_marketing_analysis_status(aid);IF r->>'status'<>'queued' OR (r->>'workerSucceeded')::boolean THEN RAISE EXCEPTION 'QUEUED_NOT_READY_FAIL';END IF;
UPDATE ccpun_admin.local_ai_job SET status='succeeded',review_status='pending',output_json=p,output_digest=repeat('f',64),completed_at=now(),model_name='qwen3:1.7b' WHERE job_id=jid;
