BEGIN PERFORM ccpun_admin.admin_validate_marketing_analysis(aid,repeat('a',64));RAISE EXCEPTION 'WRONG_DIGEST_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM='WRONG_DIGEST_ACCEPTED' THEN RAISE;END IF;END;
r:=ccpun_admin.admin_validate_marketing_analysis(aid,repeat('f',64));IF r->>'status'<>'ready' THEN RAISE EXCEPTION 'VALIDATION_PERSIST_FAIL';END IF;
r:=ccpun_admin.admin_read_marketing_analysis('this_week');IF r#>>'{lastGood,analysisId}'<>aid::text OR r#>'{lastGood,output}' IS NULL THEN RAISE EXCEPTION 'LAST_GOOD_FAIL';END IF;
IF has_table_privilege('ccpun_admin_runtime','ccpun_admin.marketing_analysis','SELECT') OR has_function_privilege('ccpun_local_ai_runtime','ccpun_admin.admin_validate_marketing_analysis(uuid,text)','EXECUTE') THEN RAISE EXCEPTION 'PRIVILEGE_FAIL';END IF;
PERFORM ccpun_admin.admin_read_marketing_v2('rolling_7',now());
RAISE NOTICE 'MARKETING_AI_FIXTURE_PASS';END $fixture$;
DO $measurement_fixture$ DECLARE e date:=(now() AT TIME ZONE 'America/Los_Angeles')::date-3;act jsonb;pid uuid;bid uuid:='00000000-0000-4000-8000-00000000b121';bid2 uuid:='00000000-0000-4000-8000-00000000b122';BEGIN
PERFORM ccpun_admin.admin_sync_marketing_identity(jsonb_build_array(jsonb_build_object('assetId','site:measurement-fixture','canonicalUrl','https://ccpun.com/measurement-fixture','title','Synthetic measurement','category','UAT','topic',NULL,'searchIntent',NULL,'contentType','test','publishedAt',NULL,'status','published','revision','synthetic-v1','aliases',jsonb_build_array(jsonb_build_object('url','https://ccpun.com/measurement-fixture','method','site-route')))));
act:=ccpun_admin.admin_save_marketing_action(jsonb_build_object('version',0,'assetId','site:measurement-fixture','priority','medium','actionType','investigation','description','Synthetic measurement fixture','expectedMetric','organic_sessions','owner','UAT','status','measuring','executedAt',(e-7)::timestamptz,'measurementDays',7,'notes','','hypothesis','','confounderNotes',''));
pid:=(act->>'id')::uuid;
-- UAT has no complete GA4 daily history before this fixture.
IF(SELECT baseline_covered FROM ccpun_admin.marketing_action WHERE action_id=pid) THEN RAISE EXCEPTION 'INCOMPLETE_BASELINE_PINNED';END IF;
