PERFORM ccpun_admin.admin_capture_marketing_measurements();IF(SELECT baseline_value FROM ccpun_admin.marketing_action WHERE action_id=pid)<>7 OR NOT(SELECT baseline_covered FROM ccpun_admin.marketing_action WHERE action_id=pid) THEN RAISE EXCEPTION 'DEFERRED_MATURE_BASELINE_FAIL';END IF;
IF(SELECT(observation->>'result')::numeric FROM ccpun_admin.marketing_action_measurement WHERE action_id=pid)<>7 THEN RAISE EXCEPTION 'POST_MEASUREMENT_FAIL';END IF;
INSERT INTO ccpun_admin.analytics_daily_batch(batch_id,source,collection_date,collection_key,status,completed_at) VALUES(bid2,'ga4',current_date,'uat:measurement-2','completed',now());
